// Static game data loaded once at boot (generated by scripts/build-data.mjs).
export const DEX = {};
export const MOVES = {};
export const LEARN = {};
export const TYPES = {};
export const BY_NAME = {};

export async function loadData() {
  const files = ['pokedex', 'moves', 'learnsets', 'types'];
  const [dex, moves, learn, types] = await Promise.all(
    files.map(f => fetch(`/data/${f}.json`).then(r => {
      if (!r.ok) throw new Error(`Failed to load ${f}.json`);
      return r.json();
    }))
  );
  Object.assign(DEX, dex);
  Object.assign(MOVES, moves);
  Object.assign(LEARN, learn);
  Object.assign(TYPES, types);
  for (const [id, s] of Object.entries(DEX)) {
    s.id = +id;
    BY_NAME[s.n.toLowerCase()] = +id;
  }
}

export const REGIONS = [
  { name: 'Kanto', last: 151, starters: [1, 4, 7] },
  { name: 'Johto', last: 251, starters: [152, 155, 158] },
  { name: 'Hoenn', last: 386, starters: [252, 255, 258] },
  { name: 'Sinnoh', last: 493, starters: [387, 390, 393] },
  { name: 'Unova', last: 649, starters: [495, 498, 501] },
  { name: 'Kalos', last: 721, starters: [650, 653, 656] },
  { name: 'Alola', last: 809, starters: [722, 725, 728] },
  { name: 'Galar', last: 905, starters: [810, 813, 816] },
  { name: 'Paldea', last: 1025, starters: [906, 909, 912] },
];
export const regionOf = id => REGIONS.findIndex(r => id <= r.last);

export function idOf(name) {
  const id = BY_NAME[name.toLowerCase()];
  if (!id) throw new Error('Unknown species: ' + name);
  return id;
}

const SPRITES = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites';
export const spriteUrl = (id, { back = false, shiny = false } = {}) =>
  `${SPRITES}/pokemon/${back ? 'back/' : ''}${shiny ? 'shiny/' : ''}${id}.png`;
export const artUrl = id => `${SPRITES}/pokemon/other/official-artwork/${id}.png`;
export const itemIconUrl = slug => `${SPRITES}/items/${slug}.png`;
export const cryUrl = id => `https://raw.githubusercontent.com/PokeAPI/cries/main/cries/pokemon/latest/${id}.ogg`;

export const TYPE_COLORS = {
  Normal: '#9fa19f', Fire: '#e62829', Water: '#2980ef', Electric: '#fac000', Grass: '#3fa129', Ice: '#3dcef3',
  Fighting: '#ff8000', Poison: '#9141cb', Ground: '#915121', Flying: '#81b9ef', Psychic: '#ef4179', Bug: '#91a119',
  Rock: '#afa981', Ghost: '#704170', Dragon: '#5060e1', Dark: '#624d4e', Steel: '#60a1b8', Fairy: '#ef70ef',
};

export function typeEffect(moveType, defTypes) {
  let m = 1;
  for (const t of defTypes) m *= TYPES[moveType]?.[t] ?? 1;
  return m;
}

/** Level-up moves a species knows at `level` (the last four learned, like wild Pokémon in the games). */
export function movesAtLevel(id, level) {
  const list = (LEARN[id] || []).filter(([lv]) => lv <= level && lv > 0);
  const seen = new Set();
  const out = [];
  for (let i = list.length - 1; i >= 0 && out.length < 4; i--) {
    const m = list[i][1];
    if (!seen.has(m)) { seen.add(m); out.unshift(m); }
  }
  // Make sure there is at least one damaging move
  if (!out.some(m => MOVES[m].c !== 'S')) {
    const dmg = list.map(x => x[1]).reverse().find(m => MOVES[m].c !== 'S') || 'tackle';
    if (out.length >= 4) out.shift();
    out.push(dmg);
  }
  return out;
}

/** Moves newly learned when reaching exactly `level` (0 = on evolution). */
export const movesLearnedAt = (id, level) => (LEARN[id] || []).filter(([lv]) => lv === level).map(x => x[1]);
